async function createHeader() {
  const header = figma.createFrame();
  header.name = "Header";
  header.resize(375, 60);
  header.layoutMode = 'HORIZONTAL';
  header.primaryAxisAlignItems = 'SPACE_BETWEEN';
  header.counterAxisAlignItems = 'CENTER';
  header.paddingLeft = 16;
  header.paddingRight = 16;

  // Add instances
  const logo = figma.getNodeById(ids.Logo_Open_Fashion).createInstance();
  header.appendChild(logo);

  const rightIcons = figma.createFrame();
  rightIcons.name = "Icons";
  rightIcons.layoutMode = 'HORIZONTAL';
  rightIcons.appendChild(figma.getNodeById(ids.Icon_Search).createInstance());
  rightIcons.appendChild(figma.getNodeById(ids.Icon_Bag).createInstance());
  header.appendChild(rightIcons);

  return header;
}

